}
function checkEvidence(evidence, code, allowRedacted) {
    const known = new Set();
    for (const item of evidence) {
        requireCondition(!known.has(item.id), code, `Duplicate evidence ID ${item.id}`);
        known.add(item.id);
        requireCondition(allowRedacted || !item.passageUnavailable, code, `Evidence passage unavailable ${item.id}`);
        if (!item.passageUnavailable)
            requireCondition(hashPassage(item.passage) === item.contentHash, code, `Passage hash mismatch ${item.id}`);
